import { Audio } from "@remotion/media";
import { interpolate, staticFile, useVideoConfig } from "remotion";
import type { Cue, Duck, Sfx, Vo } from "./timeline";

export type { Cue, Duck, Sfx };

const SFX_GAIN: Record<Sfx, number> = { whoosh: 0.32, tick: 0.22, hit: 0.3, chime: 0.26 };

// Music bed (original, generated by scripts/make_audio.py) ducked under every caption and
// callout, plus UI sounds on cues. Times are composition frames.
// Under a voice line the bed drops to `voiceTo` (about 11 dB down), deeper than under a caption.
export const Sound: React.FC<{ bed: string; ducks: Duck[]; cues: Cue[]; voices?: Vo[]; level?: number; duckTo?: number; voiceTo?: number }> = ({ bed, ducks, cues, voices = [], level = 0.5, duckTo = 0.26, voiceTo = 0.14 }) => {
  const { fps } = useVideoConfig();
  const volume = (f: number) => {
    let v = level;
    for (const w of ducks) {
      const d = interpolate(f, [w.from - 6, w.from + 2, w.to - 2, w.to + 8], [0, 1, 1, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
      v = Math.min(v, level - (level - (w.deep ? voiceTo : duckTo)) * d);
    }
    return v;
  };
  return (
    <>
      <Audio name="Music bed" src={staticFile(bed)} volume={volume} premountFor={fps} />
      {voices.map((v, i) => (
        <Audio key={`vo${i}`} name={`Voice ${i + 1}`} from={v.at} durationInFrames={v.frames + 6} premountFor={fps} src={staticFile(v.src)} volume={1} />
      ))}
      {cues.map((c, i) => (
        <Audio key={i} name={`sfx ${c.sfx}`} from={Math.max(0, Math.round(c.at))} durationInFrames={2 * fps} premountFor={fps} src={staticFile(`audio/sfx/${c.sfx}.wav`)} volume={c.volume ?? SFX_GAIN[c.sfx]} />
      ))}
    </>
  );
};
